const CACHE='future-compass-20261008-v56-fampin';
const ASSETS=["study-log.js","focus-mode.js","push.js","kid-plus.js","app-nav.js","parent-view.js","cozy-study-sm.webp","talk-note.js","shiro-study.js","planner.js","study-app.js","study-app.css","characters.js","route.js","family-sync.js","today.html","today-view.js","academy.js","usage.js","curriculum-kr.js","holidays-kr.js","study-week.js","school-config.js","school-today.js","school.json","hub.html","hub/study-hub.js","hub/study-hub.css","hub/study-hub-data.js","hub/sites.json","hub/routes.json","future.html","future-link.js","pin-gate.js","pin-gate.css","share-cover-v2.jpg","study-device.js","study-next.js","study-plus.js","study.html","study.js","study.css","focus-ui.js","focus-ui.css","shiro-help.js","shiro-help.css","know-me.html","know-me.css","know-me.js","know-me-data.js","know-me-entry.js","career-depth.js", "career-depth.css", "career-lab.js", "career-lab.css", "phone-friend.jpg", "cozy-study.jpg", "future-friend.jpg", "shiro-letter.jpg", "./", "index.html", "ui.css", "app.css", "explore.js", "shell.js", "news.js", "news.json", "manifest.webmanifest", "app-icon.svg", "app-icon-192.png", "app-icon-512.png", "icons/stethoscope.svg", "icons/newspaper.svg", "icons/heart.svg", "icons/arrow-up-right.svg", "icons/building-2.svg", "icons/palette.svg", "icons/leaf.svg", "icons/shield-check.svg", "icons/chart-no-axes-combined.svg", "icons/house.svg", "icons/lightbulb.svg", "icons/graduation-cap.svg", "icons/flask-conical.svg", "icons/sparkles.svg", "icons/circle-check.svg", "icons/bot.svg", "icons/download.svg", "icons/wheat.svg", "icons/menu.svg", "icons/book-open.svg", "icons/compass.svg", "icons/cpu.svg"];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const asset of ASSETS){try{const r=await fetch(asset,{cache:'reload'});if(r.ok&&!r.redirected)await cache.put(asset,r)}catch{}}})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('future-compass-')&&key!==CACHE)await caches.delete(key);await self.clients.claim()})()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;const relative=url.pathname.slice(new URL(self.registration.scope).pathname.length);if(event.request.mode==='navigate'&&!['','index.html'].includes(relative))return;if(event.request.mode!=='navigate'&&!ASSETS.includes(relative))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);try{const response=await fetch(event.request);if(response.ok&&!response.redirected)await cache.put(event.request,response.clone());return response}catch{return await cache.match(event.request)||await cache.match(event.request.mode==='navigate'?'index.html':relative)||new Response('Offline',{status:503})}})())});
self.addEventListener('push',event=>{let d={};try{d=event.data?event.data.json():{}}catch{d={body:event.data?event.data.text():''}}event.waitUntil(self.registration.showNotification(d.title||'승준 공부관리 방',{body:d.body||'',icon:'app-icon-192.png',badge:'app-icon-192.png',tag:d.tag||undefined,renotify:!!d.tag,data:{url:d.url||'study.html#today'}}))});
self.addEventListener('notificationclick',event=>{event.notification.close();const url=new URL((event.notification.data&&event.notification.data.url)||'study.html#today',self.registration.scope).href;event.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(list=>{for(const c of list){if(c.url.startsWith(self.registration.scope)&&'focus' in c){if('navigate' in c)c.navigate(url);return c.focus()}}return clients.openWindow(url)}))});
